// Simplex noise function (classic 2D noise)
vec2 hash(vec2 p) {
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return fract(sin(p) * 43758.5453123) * 2.0 - 1.0;
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    vec2 u = f * f * (3.0 - 2.0 * f); // Smooth interpolation

    return mix(mix(dot(hash(i + vec2(0.0, 0.0)), f - vec2(0.0, 0.0)),
                   dot(hash(i + vec2(1.0, 0.0)), f - vec2(1.0, 0.0)), u.x),
               mix(dot(hash(i + vec2(0.0, 1.0)), f - vec2(0.0, 1.0)),
                   dot(hash(i + vec2(1.0, 1.0)), f - vec2(1.0, 1.0)), u.x), u.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates to [-1, 1], with aspect ratio
    vec2 uv = fragCoord.xy / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // Animation effect
    float time = iTime * 0.2; // Control animation speed
    vec2 animatedUv = uv + vec2(sin(time), cos(time)) * 0.3;

    // Generate layered noise for topographic effect
    float n = noise(animatedUv * 3.0); // Base noise frequency

    // Tweak contour generation for clean, consistent lines
    float contours = abs(fract(n * 8.0) - 0.5); // Adjust frequency for tighter lines
    contours = smoothstep(0.02, 0.05, contours); // Narrow range to reduce blur

    // Create line color and background
    vec3 lineColor = vec3(0.2, 0.2, 0.2);  // Dark gray for lines
    vec3 backgroundColor = vec3(1.0);      // White background
    vec3 finalColor = mix(backgroundColor, lineColor, contours);

    // Output the final color
    fragColor = vec4(finalColor, 1.0);
}
